# Public API (cmgr:*)
  @api cmgr:register(name, fn, undoDesc)  @ 125
      @contract  delegates to the global scope — root-level commands are gated-to-global, which is always reachable; the duplicated registration body now lives only in scope:register  @ 124
  @api cmgr:registerAll(tbl)  @ 126
  @api cmgr:rootKeymap()  @ 129
      @contract  returns the bottom-of-stack ('global') keymap directly — used by dispatchers that want to fire ONLY root bindings (e.g. trackerPage's swing editor wants playPause/quit live but page-scoped commands off)  @ 128
  @api cmgr:bind(name, keys)  @ 131
  @api cmgr:bindAll(tbl)  @ 132
  @api cmgr:wrap(name, wrapper)  @ 135-139
      @contract  wrap is a no-op if name has no registered command; wrappers stack (compose outward)  @ 134
  @api cmgr:doBefore(name, before)  @ 144-152
      @contract  doBefore/doAfter accept either a single name or an array of names  @ 141
      @contract  doAfter preserves the original command's return values (the dispatch signal)  @ 142
      @invariant  wraps compose inside the gate — when invoke skips a gated command, no doBefore / doAfter side-effect fires  @ 143
  @api cmgr:doAfter(name, after)  @ 154-164
  @api cmgr:beginPrefix()  @ 186
      @contract  buffer accepts only '0'..'9' and '/'; cancel/finish/invoke each leave the state inactive  @ 185
  @api cmgr:isPrefixActive()  @ 187
  @api cmgr:appendPrefix(ch)  @ 189-193
  @api cmgr:cancelPrefix()  @ 195
  @api cmgr:finishPrefix()  @ 198-216
      @contract  empty buffer or unparseable input → nil pending value; '/' with empty numerator or denominator parses as nil; integer N stored as (N/1)  @ 197
  @api cmgr:prefixRational()  @ 219-221
      @contract  non-consuming reader of the parsed rational; safe to call inside a command body. Returns (nil, nil) when no prefix is pending. State is cleared at the end of invoke, not by this call.  @ 218
  @api cmgr:scope(name)  @ 226-233
      @contract  creates the scope on first request; idempotent thereafter  @ 225
  @api cmgr:push(s)  @ 238-242
      @contract  push(name|scope); creates a named scope if absent. Top-of-stack is the most recently pushed.  @ 237
  @api cmgr:pop(s)  @ 245-249
      @contract  pop(name|scope) asserts the named scope is currently on top; pops it  @ 244
  @api cmgr:lastCommand()  @ 257
      @contract  name and serial of the last body run; unknown or gated-out changes neither  @ 256
  @api cmgr:invoke(name, ...)  @ 262-282
      @contract  returns nil when the command is unknown OR registered on a scope that is not currently reachable (off-stack or blocked by a modal above)  @ 259
      @contract  always prepends the pending prefix (defaulted to 1 when nothing is pending) as the first argument to the command body. Bodies that need to distinguish "user typed 1" from "no prefix" read prefixRational() — it returns (nil, nil) when nothing is pending. State stays live for the call so the body may read it; cleared on return ONLY if there was a pending prefix at entry, so a command body that opens prefix mode (beginPrefix) is not wiped out by its own invoke.  @ 260
      @contract  spring-loaded scope: redirect[] runs fn in-place; keepAlive[] passes; else onBail()  @ 261
  @api cmgr:keysFor(name)  @ 298
  @api cmgr:keychain()  @ 301-318
      @contract  returns one keymap per stack scope in top-down order; modal scopes filter lower keymaps to their passthrough name set, then halt the walk  @ 300
  @api cmgr:keySpec(spec, ImGui)  @ 321-326
      -- ImGui injected so cmgr stays free of REAPER-side imports at module load.
  @api cmgr:commandAtKey(spec, exceptName, ImGui)  @ 332-344
      @contract  reachable command for spec's key (keychain top-down); skips exceptName; nil if free  @ 331
  @api cmgr:bindingSite(name)  @ 347-354
      @contract  scope to edit name's binding in: scope currently binding it, else its gate scope  @ 346
  @api cmgr:noteChars(char)  @ 360-362
      -- Re-read noteLayout on each call so a config change takes effect
      -- without rebuilding vm.
  @api cmgr:keyLabel(spec, ImGui)  @ 449-461
  @api cmgr:keyLabelList(name, ImGui)  @ 464-470
      @contract  list of human labels, one per bound keyspec of the reachable command, or nil if unbound  @ 463
  @api cmgr:keyLabels(name, ImGui)  @ 473-476
      @contract  keyLabelList joined by ' / ', or nil if unbound on the current stack  @ 472
  @api cmgr:tokenForSpec(spec, ImGui)  @ 538-549
      @contract  spec -> stable ASCII token ("Ctrl+Z"); nil if the key has no token name  @ 537
  @api cmgr:specForToken(token, ImGui)  @ 552-567
      @contract  token -> keyspec (bare key | {key, mod...}); (nil, err) on an unknown key/modifier  @ 551
  -- Binding overrides (persisted, hand-editable)
  @api cmgr:loadOverrides(ImGui)  @ 573-588
      @contract  a malformed token is warned and skipped; the command keeps its other (good) bindings  @ 572
  @api cmgr:rebind(scopeName, name, specs, ImGui)  @ 591-601
      @contract  overwrites the scope's binding for name and persists it as tokens (global tier)  @ 590

